(()=>{
const V="2026.09.16.3",FRESH=90,STALE=180,REFRESH=300000,POINTS={an_thoi:"An Thới",duong_dong:"Dương Đông",ganh_dau:"Gành Dầu",rach_gia:"Rạch Giá"};
const $=id=>document.getElementById(id),n=v=>v===null||v===undefined||v===""||Number.isNaN(Number(v))?null:Number(v),fmt=(v,d=1)=>{v=n(v);return v===null?"-":Number(v.toFixed(d)).toString()},esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const blank=name=>({name,status:"UNAVAILABLE",temperature:null,wind:null,gust:null,wave:null,wave_max:null,period:null,rain:null,current:null,caveat:"",hours:[],daily_outlook:[]});
function hour(r={}){return {time:String(r.time||""),time_iso:String(r.time_iso||""),temperature:n(r.temperature??r.temp),wind:n(r.wind),gust:n(r.gust),rain:n(r.rain),wave:n(r.wave),wave_max:n(r.wave_max),period:n(r.period),current:n(r.current)}}
function point(raw,key){const p=raw&&typeof raw==="object"?raw:{};return {name:String(p.name||POINTS[key]),status:String(p.status||"UNAVAILABLE"),temperature:n(p.temperature??p.temp),wind:n(p.wind),gust:n(p.gust),wave:n(p.wave),wave_max:n(p.wave_max),period:n(p.period),rain:n(p.rain),current:n(p.current),caveat:String(p.caveat||""),hours:Array.isArray(p.hours)?p.hours.map(hour):[],daily_outlook:Array.isArray(p.daily_outlook)?p.daily_outlook.filter(Boolean):[]}}
function normalize(x){x=x&&typeof x==="object"?x:{};const points={};Object.keys(POINTS).forEach(k=>points[k]=point(x.points?.[k],k));const sources={};Object.entries(x.sources&&typeof x.sources==="object"?x.sources:{}).forEach(([k,v])=>sources[k]={status:String(v?.status||"UNRESOLVED"),detail:String(v?.detail||"")});return {...x,snapshot_id:String(x.snapshot_id||"INVALID_SNAPSHOT"),generated_at:String(x.generated_at||"1970-01-01T07:00:00.000+07:00"),data_mode:String(x.data_mode||"-"),report_status:String(x.report_status||"UNAVAILABLE"),decision:String(x.decision||"NOT_ISSUED"),headline:String(x.headline||""),next_review:String(x.next_review||"sau cycle kế tiếp"),git_commit_sha:String(x.git_commit_sha||"-"),forecast_horizon_hours:n(x.forecast_horizon_hours)||72,completeness:n(x.completeness)||0,confidence:n(x.confidence),sources,gaps:Array.isArray(x.gaps)?x.gaps.filter(Boolean):[],points}}
const rawFetch=window.fetch.bind(window);window.fetch=(input,init)=>{const u=typeof input==="string"?input:input?.url||"";if(!u.includes("/weather/dashboard-data.json"))return rawFetch(input,init);return rawFetch(input,{...init,cache:"no-store"}).then(async res=>{if(!res.ok)return res;const data=normalize(await res.clone().json());return {ok:true,status:res.status,json:async()=>data}})};
function icon(name){const p={temp:'<path d="M14 14.8V5a4 4 0 1 0-8 0v9.8a6 6 0 1 0 8 0Z"/><path d="M10 7v9"/>',wind:'<path d="M3 8h9a3 3 0 1 0-3-3M3 12h14a3 3 0 1 1-3 3M3 16h6"/>',gust:'<path d="M3 7h12a3 3 0 1 0-3-3M3 12h17M3 17h10a3 3 0 1 1-3 3"/>',wave:'<path d="M2 13c2.5 0 2.5-3 5-3s2.5 3 5 3 2.5-3 5-3 2.5 3 5 3M2 18c2.5 0 2.5-3 5-3s2.5 3 5 3 2.5-3 5-3 2.5 3 5 3"/>',period:'<path d="M3 12h3l2-5 4 10 2-5h7"/>',rain:'<path d="M7 17l-1 3M12 17l-1 3M17 17l-1 3M5 14h13a4 4 0 0 0 .4-8A6 6 0 0 0 7.2 7.5 3.5 3.5 0 0 0 5 14Z"/>',current:'<path d="M4 8h13l-3-3M20 16H7l3 3"/>',home:'<path d="m3 11 9-7 9 7v9h-6v-6H9v6H3Z"/>',chart:'<path d="M4 19V9M10 19V5M16 19v-7M22 19V3"/>',table:'<path d="M4 5h16v14H4zM4 10h16M10 5v14"/>',source:'<circle cx="12" cy="12" r="8"/><path d="M12 4v16M4 12h16"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.source}</svg>`}
const MEDIA={an_thoi:{img:"https://commons.wikimedia.org/wiki/Special:FilePath/An%20Thoi%20port.jpg?width=1400",txt:"Dương Đăng Khôi · CC BY-SA · Wikimedia Commons",href:"https://commons.wikimedia.org/wiki/File:An_Thoi_port.jpg"},duong_dong:{img:"https://commons.wikimedia.org/wiki/Special:FilePath/DuongDong.jpg?width=1400",txt:"Doron · CC BY-SA 3.0 · Wikimedia Commons",href:"https://commons.wikimedia.org/wiki/File:DuongDong.jpg"},ganh_dau:{img:"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%90%E1%BB%81n%20th%E1%BB%9D%20Nguy%E1%BB%85n%20Trung%20Tr%E1%BB%B1c%20%E1%BB%9F%20Ph%C3%BA%20Qu%E1%BB%91c.JPG?width=1400",txt:"Tokeisan · CC BY-SA 3.0 · Wikimedia Commons",href:"https://commons.wikimedia.org/wiki/File:%C4%90%E1%BB%81n_th%E1%BB%9D_Nguy%E1%BB%85n_Trung_Tr%E1%BB%B1c_%E1%BB%9F_Ph%C3%BA_Qu%E1%BB%91c.JPG"},rach_gia:{img:"https://commons.wikimedia.org/wiki/Special:FilePath/Khu%20l%E1%BA%A5n%20bi%E1%BB%83n%20%E1%BB%9F%20R%E1%BA%A1ch%20Gi%C3%A1%2C%20Ki%C3%AAn%20Giang.jpg?width=1400",txt:"Dongson.vmvn · CC BY-SA 3.0 · Wikimedia Commons",href:"https://commons.wikimedia.org/wiki/File:Khu_l%E1%BA%A5n_bi%E1%BB%83n_%E1%BB%9F_R%E1%BA%A1ch_Gi%C3%A1,_Ki%C3%AAn_Giang.jpg"}};
function inject(){if(!$("freshnessBanner")){const e=document.createElement("div");e.id="freshnessBanner";e.className="freshness-banner";e.hidden=true;document.querySelector(".control-shell")?.insertAdjacentElement("afterend",e)}if(!$("diagnosticBanner")){const e=document.createElement("div");e.id="diagnosticBanner";e.className="diagnostic-banner";e.hidden=true;document.querySelector("main")?.prepend(e)}if(!$("heroCredit")){const e=document.createElement("a");e.id="heroCredit";e.className="hero-credit";e.target="_blank";e.rel="noopener noreferrer";document.querySelector(".hero-card")?.appendChild(e)}if(!$("chartTooltip")){const e=document.createElement("div");e.id="chartTooltip";e.className="chart-tooltip";e.hidden=true;document.querySelector(".chart-wrap")?.appendChild(e)}const mi=["temp","wind","gust","wave","wave","period","rain","current"];document.querySelectorAll(".metric").forEach((e,i)=>{if(e.classList.contains("icon-enhanced"))return;e.classList.add("icon-enhanced");const s=document.createElement("span");s.className="metric-icon";s.innerHTML=icon(mi[i]);e.prepend(s)});const dock=document.querySelector(".app-dock");dock?.querySelectorAll("button").forEach((b,i)=>{b.classList.add("has-svg");const sp=b.querySelector("span");b.innerHTML=icon(["home","chart","table","source"][i])+(sp?sp.outerHTML:`<span>${b.textContent}</span>`)})}
function pwa(){if(!document.querySelector('link[rel="manifest"]')){const l=document.createElement("link");l.rel="manifest";l.href=`/weather-manifest.webmanifest?v=${V}`;document.head.appendChild(l)}if(!document.querySelector('link[data-weather-icon]')){const l=document.createElement("link");l.rel="icon";l.type="image/svg+xml";l.href=`/weather-app-icon.svg?v=${V}`;l.dataset.weatherIcon="1";document.head.appendChild(l)}if(!document.querySelector('meta[name="apple-mobile-web-app-capable"]')){const m=document.createElement("meta");m.name="apple-mobile-web-app-capable";m.content="yes";document.head.appendChild(m)}if("serviceWorker" in navigator&&location.protocol==="https:")navigator.serviceWorker.register(`/weather-sw.js?v=${V}`,{scope:"/"}).catch(()=>{})}
function ageMin(){const t=Date.parse(state?.generated_at);return Number.isFinite(t)?Math.max(0,(Date.now()-t)/60000):Infinity}
function freshness(){const m=ageMin();return m<=FRESH?{l:"fresh",m}:m<=STALE?{l:"delayed",m}:{l:"stale",m}}
function freshUI(){const f=freshness(),declared=state?.report_status==="LIVE",dot=$("healthDot"),b=$("freshnessBanner"),label=Number.isFinite(f.m)?(f.m<60?`${Math.round(f.m)} phút`:`${Math.round(f.m/60)} giờ`):"không xác định";document.body.dataset.freshness=f.l;if(dot)dot.className=`dot ${declared&&f.l==="fresh"?"ok":f.l==="delayed"?"warn":"stale"}`;if($("cycleText"))$("cycleText").textContent=`${declared&&f.l==="fresh"?"LIVE":f.l==="delayed"?"DELAYED":"STALE"} · cập nhật ${label} trước`;if(b){b.hidden=f.l==="fresh";b.className=`freshness-banner ${f.l}`;b.textContent=f.l==="delayed"?`Dữ liệu đang chậm ${label}. Có thể xem xu hướng nhưng nên chờ snapshot mới trước quyết định sát giờ.`:`Dữ liệu đã cũ ${label}. Không dùng snapshot này để chốt vận hành.`}}
function future24(p){const now=Date.now(),cut=now+86400000;return (p.hours||[]).filter(r=>{const t=Date.parse(r.time_iso);return Number.isFinite(t)&&t>=now&&t<=cut})}
function summary(p){const a=future24(p),g=Math.max(n(p.gust)||0,...a.map(r=>n(r.gust)||0)),h=Math.max(n(p.wave_max)||0,...a.map(r=>n(r.wave_max)||0)),rain=a.reduce((s,r)=>s+(n(r.rain)||0),0),w=a.map(r=>n(r.wind)).filter(v=>v!==null),q=[];q.push(h>=2.4||g>=45?"Biên gió hoặc sóng cá thể có lúc tăng cao trong 24 giờ tới":h>=1.7||g>=32?"Biển có thời điểm động hơn mức hiện tại trong 24 giờ tới":"Gió và sóng trong 24 giờ tới chưa cho thấy biến động lớn trên snapshot hiện tại");if(rain>=15)q.push("mưa tích lũy đáng kể");else if(rain>=3)q.push("có các kỳ mưa rải rác");if(w.length>2&&w[w.length-1]-w[0]>=8)q.push("gió có xu hướng tăng về cuối khoảng theo dõi");else if(w.length>2&&w[0]-w[w.length-1]>=8)q.push("gió có xu hướng giảm về cuối khoảng theo dõi");return `${q.join("; ")}. Tóm tắt dữ liệu, không thay thế quyết định vận hành.`}
function heroUI(){const p=state?.points?.[currentPoint]||blank(POINTS[currentPoint]),m=MEDIA[currentPoint],hero=document.querySelector(".hero-card"),c=$("heroCredit");if($("heroHeadline"))$("heroHeadline").textContent=summary(p);if(hero)hero.style.setProperty("--hero-image",m?`url("${m.img}")`:"none");if(c&&m){c.hidden=false;c.textContent=`Ảnh: ${m.txt}`;c.href=m.href}}
function safeSources(){const root=$("sources");if(root)root.innerHTML=Object.entries(state?.sources||{}).map(([k,v])=>`<div class="source"><b>${esc(k)}</b><span><i class="state ${v.status==="PASS"?"ok":v.status==="PARTIAL"?"partial":"fail"}">${esc(v.status)}</i><br>${esc(v.detail)}</span></div>`).join("")||`<div class="gap"><b>Chưa có nguồn</b><span>Snapshot không khai báo nguồn dữ liệu.</span></div>`;const gaps=$("gaps");if(gaps)gaps.innerHTML=(state?.gaps||[]).length?state.gaps.map(x=>`<div class="gap"><b>${esc(x?.name||"Data gap")}</b><span>${esc(x?.detail||"")}</span></div>`).join(""):`<div class="gap"><b>Không có critical gap</b><span>Cycle đủ điều kiện</span></div>`}
function report(msg){console.error(msg);const e=$("diagnosticBanner");if(e){e.hidden=false;e.dataset.level="error";e.textContent=`Giao diện gặp lỗi cục bộ: ${msg}. Dữ liệu nền vẫn được giữ; thử tải lại trang nếu phần hiển thị chưa cập nhật.`}}
addEventListener("error",e=>report(e.message||"JavaScript error"));addEventListener("unhandledrejection",e=>report(String(e.reason||"Promise error")));
let rows=[];function tooltip(e,r){const t=$("chartTooltip"),wrap=document.querySelector(".chart-wrap");if(!t||!wrap||!r)return;t.innerHTML=`<b>${esc(r.time)}</b><div class="chart-tooltip-grid"><span>Nhiệt độ</span><span>${fmt(r.temperature,1)}°C</span><span>Gió / giật</span><span>${fmt(r.wind,1)} / ${fmt(r.gust,1)} km/h</span><span>Hs / Hmax</span><span>${fmt(r.wave,2)} / ${fmt(r.wave_max,2)} m</span><span>Mưa</span><span>${fmt(r.rain,2)} mm</span></div>`;t.hidden=false;const wr=wrap.getBoundingClientRect(),x=Math.max(95,Math.min(wr.width-95,e.clientX-wr.left)),y=Math.max(82,e.clientY-wr.top);t.style.left=`${x}px`;t.style.top=`${y}px`}
function pointer(){const c=$("forecastChart");if(!c||c.dataset.tip)return;c.dataset.tip="1";const h=e=>{if(!rows.length)return;const r=c.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));tooltip(e,rows[Math.round(ratio*(rows.length-1))])};c.addEventListener("pointermove",h);c.addEventListener("pointerdown",h);c.addEventListener("pointerleave",()=>{const t=$("chartTooltip");if(t)t.hidden=true})}
function afterLegacy(){try{inject();pwa();const oldRender=render;render=function(){state=normalize(state);oldRender();freshUI();heroUI();safeSources()};const oldPoint=renderPoint;renderPoint=function(){state=normalize(state);oldPoint();heroUI()};const oldChart=drawChart;drawChart=function(r){rows=Array.isArray(r)?r:[];oldChart(r);pointer()};if(typeof render==="function")render();setInterval(()=>{freshUI();typeof load==="function"&&load()},REFRESH)}catch(e){report(e?.message||String(e))}}
window.WeatherLabEnhancements={afterLegacy,normalize};
})();